def registered_file(token: str) -> Path | None:
    try:
        entries = json.loads(REGISTRY.read_text(encoding="utf-8"))
        path = Path(entries.get(token, "")).resolve()
        return path if path.is_file() and path.suffix.lower() in {".mp4", ".mp3"} else None
    except (OSError, ValueError):
        return None


def library_payload(refresh: bool = False) -> dict:
    index = refresh_library_index(ROOT / "output") if refresh else load_library_index()
    try:
        registry = json.loads(REGISTRY.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        registry = {}
    for item in index.get("items", []):
        token = hashlib.md5(item["path"].encode("utf-8"), usedforsecurity=False).hexdigest()
        registry[token] = item["path"]
        item["playbackUrl"] = f"/play/{token}"
    REGISTRY.parent.mkdir(parents=True, exist_ok=True)
    REGISTRY.write_text(json.dumps(registry, indent=2), encoding="utf-8")
    return index


class PlaybackHandler(BaseHTTPRequestHandler):
    def send_json(self, payload: dict, status: int = 200):
        body = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        path = urlparse(self.path).path
        if path not in {
            "/api/command",
            "/api/wakeword/config",
            "/api/wakeword/pause",
            "/api/wakeword/resume",
        }:
            self.send_error(404)
            return
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length > 16 * 1024:
                raise ValueError("Invalid command request size.")
            request = json.loads(self.rfile.read(length).decode("utf-8")) if length else {}
            if path == "/api/command":
                if length < 1:
                    raise ValueError("Invalid command request size.")
                self.send_json(route_command(request.get("query", "")))
            elif path == "/api/wakeword/config":
                if not isinstance(request.get("enabled"), bool):
                    raise ValueError("Wake-word enabled must be true or false.")
                self.send_json(WAKEWORD.configure(request["enabled"]))
            elif path == "/api/wakeword/pause":
                self.send_json(WAKEWORD.pause())
            else:
                self.send_json(WAKEWORD.resume())
        except ValueError as exc:
            self.send_json({"error": str(exc)}, 400)
        except Exception as exc:
            self.send_json({"error": f"Local Needle command failed: {exc}"}, 503)

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        if path == "/api/command/status":
            self.send_json(command_status())
            return
        if path == "/api/wakeword/status":
            self.send_json(WAKEWORD.status())
            return
        if path == "/api/wakeword/wait":
            query = parse_qs(parsed.query)
            try:
                after_sequence = int(query.get("after", ["0"])[0])
                timeout = float(query.get("timeout", ["20"])[0])
            except (TypeError, ValueError):
                self.send_json({"error": "Invalid wake-word wait parameters."}, 400)
                return
            self.send_json(WAKEWORD.wait_for_detection(after_sequence, timeout))
            return
        if path == "/api/library":
            body = json.dumps(
                library_payload(parse_qs(parsed.query).get("refresh", ["0"])[0] == "1")
            ).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        if path == "/health":
            body = b"ok"
            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        if path == "/assets/vu-meter-face.svg":
            try:
                body = METER_FACE.read_bytes()
            except OSError:
                self.send_error(404, "Meter face asset not found")
                return
            self.send_response(200)
            self.send_header("Content-Type", "image/svg+xml; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)
            return
        page_match = re.fullmatch(r"/play/([A-Fa-f0-9]{32})", unquote(path))
        if page_match:
            media = registered_file(page_match.group(1))
            if media is None:
                self.send_error(404, "Karaoke file not found")
                return
            body = player_page(page_match.group(1), media)
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-store")
            self.end_headers()
            self.wfile.write(body)
            return
        match = re.fullmatch(r"/media/([A-Fa-f0-9]{32})", unquote(path))
        media = registered_file(match.group(1)) if match else None
        if media is None:
            self.send_error(404, "Karaoke file not found")
            return
        total = media.stat().st_size
        start, end, status = 0, total - 1, 200
        range_header = self.headers.get("Range", "")
        range_match = re.match(r"bytes=(\d*)-(\d*)", range_header)
        if range_match:
            if range_match.group(1):
                start = int(range_match.group(1))
            if range_match.group(2):
                end = min(end, int(range_match.group(2)))
            if start > end or start >= total:
                self.send_response(416)
                self.send_header("Content-Range", f"bytes */{total}")
                self.end_headers()
                return
            status = 206
        self.send_response(status)
        content_type = "audio/mpeg" if media.suffix.lower() == ".mp3" else "video/mp4"
        self.send_header("Content-Type", content_type)
        download_name = friendly_media_name(media).replace('"', "_")
        self.send_header("Content-Disposition", f'inline; filename="{download_name}"')
        self.send_header("Accept-Ranges", "bytes")
        self.send_header("Content-Length", str(end - start + 1))
        if status == 206:
            self.send_header("Content-Range", f"bytes {start}-{end}/{total}")
        self.end_headers()
        with media.open("rb") as source:
            source.seek(start)
            remaining = end - start + 1
            while remaining:
                chunk = source.read(min(1024 * 256, remaining))
                if not chunk:
                    break
                self.wfile.write(chunk)
                remaining -= len(chunk)

    def log_message(self, *_args):
        return


if __name__ == "__main__":
    WAKEWORD.start()
    try:
        ThreadingHTTPServer((HOST, PORT), PlaybackHandler).serve_forever()
    finally:
        WAKEWORD.stop()
